create table public.students (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete restrict, user_id uuid references public.users(id) on delete set null, student_number text not null, admission_date date, enrollment_status text not null default 'ACTIVE' check(enrollment_status in ('ACTIVE','INACTIVE','GRADUATED','WITHDRAWN')), created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(tenant_id,student_number), unique(tenant_id,user_id));
create index students_tenant_idx on public.students(tenant_id); alter table public.students enable row level security; revoke all on public.students from anon,authenticated; create policy students_select_tenant on public.students for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values ('students.read','Read students','View student profiles'),('students.create','Create students','Create student profiles'),('students.update','Update students','Maintain student profiles') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in ('OWNER','PRINCIPAL','STAFF') and p.code like 'students.%' on conflict do nothing;
